const LANG_NAMES={en:'English',es:'Español',de:'Deutsch',fr:'Français',it:'Italiano',nl:'Nederlands',pt:'Português'};
const PHONE='34615788239';
const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const wa=text=>'https://wa.me/'+PHONE+'?text='+encodeURIComponent(text);
let lang='en',filter='all',lastTrigger=null;
try{const saved=new URLSearchParams(location.search).get('lang')||localStorage.getItem('sumatra-language')||navigator.language.split('-')[0];if(UI[saved])lang=saved}catch{}
const t=key=>UI[lang][key];
const price=value=>new Intl.NumberFormat(lang,{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(value);
function art(type){const content=type==='clay'?'<path d="M40 150V90H280V150ZM20 40Q90 110 160 80Q230 110 300 40L280 98H40ZM110 150V115H140V150M185 113H225V138H185Z"/>':type==='lake'?'<path d="M5 120Q40 103 75 120T145 120T215 120T285 120T350 120M5 140Q40 123 75 140T145 140T215 140T285 140T350 140M20 110 75 55 130 110M140 110 200 30 295 110M200 30 175 73 200 65 225 74"/>':'<path d="M20 155 100 50 165 155 210 30 300 155M100 50 80 85 102 75 125 85M210 30 185 78 215 60 245 80M60 168Q110 145 130 164T220 162"/>';
return '<svg viewBox="0 0 320 192" fill="none" aria-hidden="true"><g stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">'+content+'</g></svg>'}
function renderRoutes(){q('#tour-grid').innerHTML=ROUTES.map((route,i)=>{if(filter!=='all'&&route.cat!==filter)return '';const r=R[lang][i];return `<article class="tour-card"><div class="tour-image tone-${route.type}">${route.img?`<img src="assets/${route.img}" alt="${route.place}" loading="lazy" width="600" height="350">`:art(route.type)}<span class="tag">${escapeHTML(t(route.cat))}</span>${!route.img?`<span class="photo-marker">${escapeHTML(t('photoPending'))}</span>`:''}</div><div class="card-body"><div class="eyebrow">Nº ${String(i+1).padStart(2,'0')} · ${route.place} · ${route.coord}</div><h3>${escapeHTML(r[0])}</h3><p>${escapeHTML(r[1])}</p><div class="tour-facts"><span>${route.days} ${escapeHTML(t('days'))}</span><span>${escapeHTML(t('level'))} ${route.level}/4</span></div><div class="card-bottom"><div class="price"><small>${escapeHTML(t('from'))} · ${escapeHTML(t('perPerson'))}</small><strong>${price(route.price)}</strong></div><button data-route="${i}">${escapeHTML(t('viewRoute'))}</button></div></div></article>`}).join('');qa('[data-route]').forEach(b=>b.addEventListener('click',()=>openRoute(Number(b.dataset.route),b)))}
function applyLanguage(){document.documentElement.lang=lang;q('#language').value=lang;document.title='Explore Sumatra Escape — '+t('hero').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();qa('[data-t]').forEach(el=>{const key=el.dataset.t;if(!UI[lang][key])throw new Error('Missing '+lang+':'+key);if(['hero','routesTitle','approachTitle','enquiryTitle'].includes(key))el.innerHTML=t(key);else el.textContent=t(key)});q('#language').setAttribute('aria-label',t('messageLanguage'));q('nav').setAttribute('aria-label',t('navRoutes'));q('.filters').setAttribute('aria-label',t('navRoutes'));q('.close-dialog').setAttribute('aria-label',t('close'));const tourValue=q('#tour').value;q('#tour').innerHTML=ROUTES.map((r,i)=>`<option value="${i}">${escapeHTML(R[lang][i][0])} · ${r.id}</option>`).join('')+`<option value="custom">${escapeHTML(t('custom'))}</option>`;if(tourValue)q('#tour').value=tourValue;renderRoutes();q('#season-table').innerHTML=ROUTES.map((r,i)=>`<div class="season-row"><strong>${escapeHTML(R[lang][i][0])}</strong><span>${escapeHTML(R[lang][i][2])}</span></div>`).join('');q('#story-grid').innerHTML=[0,1,2].map(i=>`<article class="story"><span class="quote-mark" aria-hidden="true">“</span><h3>${escapeHTML(t('storyTitle'))}</h3><p>${escapeHTML(t('storyBody'))}</p><dl><dt>${escapeHTML(t('guest'))}</dt><dd>${escapeHTML(t('storyPending'))}</dd><dt>${escapeHTML(t('visit'))}</dt><dd>${escapeHTML(t('storyPending'))}</dd></dl></article>`).join('');['#phone','#floating-chat'].forEach(s=>q(s).href=wa(t('messageHello')));q('#share-story').href=wa(t('storyMessage'));q('#notes').placeholder=t('notesLabel');qa('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));try{localStorage.setItem('sumatra-language',lang);const u=new URL(location.href);u.searchParams.set('lang',lang);history.replaceState(null,'',u)}catch{}}
function openRoute(i,trigger){lastTrigger=trigger;const route=ROUTES[i],r=R[lang][i];q('#tour-detail').innerHTML=`<article class="detail"><div class="eyebrow">${route.id} · ${route.coord}</div><h2 id="detail-title">${escapeHTML(r[0])}</h2><p>${escapeHTML(r[1])}</p><div class="detail-facts"><span>${route.days} ${escapeHTML(t('days'))}</span><span>${escapeHTML(t('level'))} ${route.level}/4</span><span>${escapeHTML(t('from'))} ${price(route.price)} · ${escapeHTML(t('perPerson'))}</span></div><h3>${escapeHTML(t('best'))}</h3><p>${escapeHTML(r[2])}</p><h3>${escapeHTML(t('itinerary'))}</h3><ul>${r[3].split('|').map(line=>`<li>${escapeHTML(t('day'))} ${escapeHTML(line)}</li>`).join('')}</ul><h3>${escapeHTML(t('includes'))}</h3><ul>${r[4].split('|').map(line=>`<li>${escapeHTML(line)}</li>`).join('')}</ul><h3>${escapeHTML(t('excludes'))}</h3><ul>${r[5].split('|').map(line=>`<li>${escapeHTML(line)}</li>`).join('')}</ul><p class="small">${escapeHTML(t('priceNote'))}</p><button class="button primary" id="choose-route">${escapeHTML(t('askRoute'))} ↗</button></article>`;q('#tour-dialog').setAttribute('aria-labelledby','detail-title');q('#tour-dialog').showModal();document.body.classList.add('modal-open');q('#tour-dialog').scrollTop=0;q('#choose-route').addEventListener('click',()=>{q('#tour').value=String(i);q('#tour-dialog').close();q('#enquiry').scrollIntoView({behavior:'smooth'});setTimeout(()=>q('#date').focus({preventScroll:true}),350)})}
q('#language').addEventListener('change',e=>{lang=e.target.value;applyLanguage()});qa('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;qa('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderRoutes()}));q('.close-dialog').addEventListener('click',()=>q('#tour-dialog').close());q('#tour-dialog').addEventListener('close',()=>{document.body.classList.remove('modal-open');if(lastTrigger?.isConnected)lastTrigger.focus({preventScroll:true})});q('#tour-dialog').addEventListener('click',e=>{if(e.target===q('#tour-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
const now=new Date();q('#date').min=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');
function enquiryURL(){const value=q('#tour').value;const index=value==='custom'?-1:Number(value);const route=index<0?t('custom'):R[lang][index][0]+' · '+ROUTES[index].id;const lines=[t('messageHello'),'',t('tourLabel')+': '+route,t('messageDate')+': '+q('#date').value,t('messagePeople')+': '+q('#travellers').value,t('messageName')+': '+q('#name').value.trim(),t('messageLanguage')+': '+LANG_NAMES[lang]];if(q('#notes').value.trim())lines.push(t('messageNotes')+': '+q('#notes').value.trim());return wa(lines.join('\n'))}
q('#enquiry-form').addEventListener('submit',e=>{e.preventDefault();if(!e.currentTarget.reportValidity())return;const link=document.createElement('a');link.href=enquiryURL();link.target='_blank';link.rel='noopener';document.body.append(link);link.click();link.remove()});
applyLanguage();
